#!/usr/bin/env python3
import sys
import os
import re
import json
from datetime import date, timedelta
from decimal import Decimal

def parse_sql(text):
    results = []
    pattern = r'INSERT\s+INTO\s+(\w+)\s*\(([^)]+)\)\s*VALUES\s*(.*?);'
    for match in re.finditer(pattern, text, re.IGNORECASE | re.DOTALL):
        table = match.group(1)
        cols_str = match.group(2)
        values_str = match.group(3)
        columns = [c.strip() for c in cols_str.split(',')]
        tuples = parse_value_tuples(values_str)
        results.append((table, columns, tuples))
    return results

def parse_value_tuples(s):
    tuples = []
    i = 0
    while i < len(s):
        while i < len(s) and s[i] != '(':
            i += 1
        if i >= len(s):
            break
        depth = 0
        start = i
        in_string = False
        while i < len(s):
            c = s[i]
            if c == "'" and not in_string:
                in_string = True
            elif c == "'" and in_string:
                if i + 1 < len(s) and s[i+1] == "'":
                    i += 1
                else:
                    in_string = False
            elif c == '(' and not in_string:
                depth += 1
            elif c == ')' and not in_string:
                depth -= 1
                if depth == 0:
                    break
            i += 1
        if i >= len(s):
            break
        tuple_str = s[start+1:i]
        values = parse_values(tuple_str)
        tuples.append(values)
        i += 1
    return tuples

def parse_values(s):
    values = []
    i = 0
    while i < len(s):
        while i < len(s) and s[i] in ' \t\n\r':
            i += 1
        if i >= len(s):
            break
        if s[i] == "'":
            i += 1
            val_str = ''
            while i < len(s):
                if s[i] == "'":
                    if i + 1 < len(s) and s[i+1] == "'":
                        val_str += "'"
                        i += 2
                    else:
                        i += 1
                        break
                else:
                    val_str += s[i]
                    i += 1
            values.append(val_str)
        else:
            val_start = i
            while i < len(s) and s[i] != ',':
                i += 1
            val_str = s[val_start:i].strip()
            if val_str.upper() == 'NULL':
                values.append(None)
            else:
                values.append(val_str)
        while i < len(s) and s[i] in ' \t\n\r':
            i += 1
        if i < len(s) and s[i] == ',':
            i += 1
    return values

def load_file(filepath):
    with open(filepath) as f:
        text = f.read()
    inserts = parse_sql(text)
    records = {}
    for table, columns, tuples in inserts:
        for tup in tuples:
            record = dict(zip(columns, tup))
            cmp_code = record.get('cmp_code')
            if cmp_code is not None:
                records.setdefault(cmp_code, []).append(record)
    return records

def epd_to_date(epd):
    return (date(1970, 1, 1) + timedelta(days=epd)).strftime('%Y-%m-%d')

def dan_to_kn(dan):
    d = Decimal(dan) / Decimal(100)
    s = str(d)
    if '.' in s:
        s = s.rstrip('0').rstrip('.')
    return s

def get_values_from_doc(doc_data, cmp_code, column):
    records = doc_data.get(cmp_code, [])
    values = []
    for rec in records:
        val = rec.get(column)
        if val is not None:
            values.append(val)
    return values

def check_conflict(values, type_):
    normalized = set()
    for val in values:
        if type_ == 'date':
            normalized.add(int(val))
        elif type_ == 'force_kn':
            normalized.add(Decimal(val))
        else:
            normalized.add(val)
    return len(normalized) > 1

def convert_value(val, type_):
    if type_ == 'date':
        return epd_to_date(int(val))
    elif type_ == 'force_kn':
        return dan_to_kn(val)
    else:
        return str(val)

def resolve_fact(primary_doc, primary_data, primary_col,
                  fallback_doc, fallback_data, fallback_col,
                  cmp_code, type_):
    values = get_values_from_doc(primary_data, cmp_code, primary_col)
    if values:
        if check_conflict(values, type_):
            return 'CONFLICT'
        return [convert_value(values[0], type_), primary_doc]

    if fallback_doc is not None and fallback_data is not None:
        values = get_values_from_doc(fallback_data, cmp_code, fallback_col)
        if values:
            if check_conflict(values, type_):
                return 'CONFLICT'
            return [convert_value(values[0], type_), fallback_doc]

    return 'ABSENT'

def main():
    dir_path = sys.argv[1]

    file_map = {
        'calibration_log': 'calibration_log.sql',
        'lab_certificates': 'lab_certificates.sql',
        'spec_sheets': 'spec_sheets.sql',
        'test_reports': 'test_reports.sql',
    }

    docs = {}
    for doc_name, fname in file_map.items():
        fpath = os.path.join(dir_path, fname)
        if os.path.exists(fpath):
            docs[doc_name] = load_file(fpath)
        else:
            docs[doc_name] = {}

    rules = {
        'ea.calibration_current': {
            'calibration date': {
                'primary': {'doc': 'calibration_log', 'col': 'rig_cal_epd', 'type': 'date'},
                'fallback': None,
            },
            'test date': {
                'primary': {'doc': 'test_reports', 'col': 'inhouse_break_epd', 'type': 'date'},
                'fallback': {'doc': 'lab_certificates', 'col': 'lab_break_epd', 'type': 'date'},
            },
        },
        'ea.load_with_margin': {
            'measured load': {
                'primary': {'doc': 'lab_certificates', 'col': 'lab_break_dan', 'type': 'force_kn'},
                'fallback': {'doc': 'test_reports', 'col': 'inhouse_break_dan', 'type': 'force_kn'},
            },
            'specified minimum': {
                'primary': {'doc': 'spec_sheets', 'col': 'floor_force_dan', 'type': 'force_kn'},
                'fallback': None,
            },
        },
    }

    components = [f'P-401{i:02d}' for i in range(1, 17)]

    result = {}
    for rule_name, facts in rules.items():
        for cmp_code in components:
            pair_id = f'{rule_name}::{cmp_code}'
            result[pair_id] = {}
            for fact_name, fact_def in facts.items():
                p = fact_def['primary']
                f = fact_def['fallback']

                if f:
                    result[pair_id][fact_name] = resolve_fact(
                        p['doc'], docs.get(p['doc'], {}), p['col'],
                        f['doc'], docs.get(f['doc'], {}), f['col'],
                        cmp_code, p['type']
                    )
                else:
                    result[pair_id][fact_name] = resolve_fact(
                        p['doc'], docs.get(p['doc'], {}), p['col'],
                        None, None, None,
                        cmp_code, p['type']
                    )

    print(json.dumps(result, indent=2))

if __name__ == '__main__':
    main()
