import sys
import os
import json
from decimal import Decimal

def parse_edi(path):
    with open(path, 'r') as f:
        content = f.read()
    content = content.replace('\n', '').replace('\r', '')
    segments = content.split('~')
    segments = [s.strip() for s in segments if s.strip()]

    loops = []
    current_loop = None
    in_lx = False

    for seg in segments:
        parts = seg.split('*')
        tag = parts[0]

        if tag == 'LX':
            if current_loop is not None:
                loops.append(current_loop)
            current_loop = {'segments': []}
            in_lx = True
        elif tag in ('CTT', 'SE', 'GE', 'IEA'):
            if current_loop is not None:
                loops.append(current_loop)
                current_loop = None
            in_lx = False
        elif in_lx and current_loop is not None:
            current_loop['segments'].append(parts)

    if current_loop is not None:
        loops.append(current_loop)

    return loops

def get_part_key(loop):
    for seg in loop['segments']:
        if seg[0] == 'LIN':
            for i in range(1, len(seg) - 1):
                if seg[i] == 'BP':
                    return seg[i + 1]
    return None

def get_dtp_date(loop, qualifier):
    for seg in loop['segments']:
        if seg[0] == 'DTP' and len(seg) >= 4 and seg[1] == qualifier:
            date_str = seg[3]
            if len(date_str) == 8:
                return f"{date_str[0:4]}-{date_str[4:6]}-{date_str[6:8]}"
    return None

def get_mea_kn(loop, qualifier):
    for seg in loop['segments']:
        if seg[0] == 'MEA' and len(seg) >= 5 and seg[2] == qualifier:
            value = seg[3]
            unit = seg[4]
            val = Decimal(value)
            if unit == 'NT':
                val = val / Decimal(1000)
            s = format(val, 'f')
            if '.' in s:
                s = s.rstrip('0').rstrip('.')
            return s
    return None

def build_doc_index(loops):
    index = {}
    for loop in loops:
        key = get_part_key(loop)
        if key:
            if key not in index:
                index[key] = []
            index[key].append(loop)
    return index

def extract_fact(doc_indices, part, primary_doc, primary_extractor, fallback_doc=None, fallback_extractor=None):
    if primary_doc in doc_indices and part in doc_indices[primary_doc]:
        loops = doc_indices[primary_doc][part]
        values = []
        for loop in loops:
            v = primary_extractor(loop)
            if v is not None:
                values.append(v)
        if len(values) > 0:
            unique = set(values)
            if len(unique) > 1:
                return 'CONFLICT'
            return [values[0], primary_doc]

    if fallback_doc and fallback_extractor:
        if fallback_doc in doc_indices and part in doc_indices[fallback_doc]:
            loops = doc_indices[fallback_doc][part]
            values = []
            for loop in loops:
                v = fallback_extractor(loop)
                if v is not None:
                    values.append(v)
            if len(values) > 0:
                unique = set(values)
                if len(unique) > 1:
                    return 'CONFLICT'
                return [values[0], fallback_doc]

    return 'ABSENT'

def main():
    dir_path = sys.argv[1]

    doc_files = {
        'calibration_log': 'calibration_log.edi',
        'lab_certificates': 'lab_certificates.edi',
        'parts': 'parts.edi',
        'spec_sheets': 'spec_sheets.edi',
        'test_reports': 'test_reports.edi',
    }

    doc_indices = {}
    for doc_name, filename in doc_files.items():
        path = os.path.join(dir_path, filename)
        loops = parse_edi(path)
        doc_indices[doc_name] = build_doc_index(loops)

    parts_list = [f'P-401{i:02d}' for i in range(1, 17)]

    result = {}

    for part in parts_list:
        cal_key = f'ea.calibration_current::{part}'
        result[cal_key] = {
            'calibration date': extract_fact(
                doc_indices, part,
                'calibration_log',
                lambda loop: get_dtp_date(loop, '300')
            ),
            'test date': extract_fact(
                doc_indices, part,
                'test_reports',
                lambda loop: get_dtp_date(loop, '301'),
                'lab_certificates',
                lambda loop: get_dtp_date(loop, '302')
            )
        }

        load_key = f'ea.load_with_margin::{part}'
        result[load_key] = {
            'measured load': extract_fact(
                doc_indices, part,
                'lab_certificates',
                lambda loop: get_mea_kn(loop, 'UFL'),
                'test_reports',
                lambda loop: get_mea_kn(loop, 'UFH')
            ),
            'specified minimum': extract_fact(
                doc_indices, part,
                'spec_sheets',
                lambda loop: get_mea_kn(loop, 'UFM')
            )
        }

    print(json.dumps(result, indent=2))

if __name__ == '__main__':
    main()
