import sys
import os
import json
from decimal import Decimal

def parse_edi(filepath):
    with open(filepath, 'r', encoding='utf-8') as f:
        content = f.read()
    segments = [s.strip() for s in content.split('~') if s.strip()]
    loops = []
    current = None
    for seg in segments:
        parts = seg.split('*')
        tag = parts[0] if parts else ''
        if tag == 'LX':
            if current is not None:
                loops.append(current)
            current = []
        elif current is not None:
            current.append(parts)
    if current is not None:
        loops.append(current)
    return loops

def get_component(loop):
    for p in loop:
        if p[0] == 'LIN' and len(p) >= 4 and p[2] == 'BP':
            return p[3]
    return None

def extract_date(loop, qual):
    vals = []
    for p in loop:
        if p[0] == 'DTP' and len(p) >= 4 and p[1] == qual and p[2] == 'D8':
            r = p[3]
            if len(r) == 8:
                vals.append(f"{r[:4]}-{r[4:6]}-{r[6:]}")
    return vals

def extract_force(loop, quals):
    vals = []
    for p in loop:
        if p[0] == 'MEA' and len(p) >= 5 and p[1] == 'TE' and p[2] in quals:
            v, u = p[3], p[4]
            if u == 'KN':
                d = Decimal(v)
            elif u == 'NT':
                d = Decimal(v) / Decimal('1000')
            else:
                continue
            s = str(d)
            if '.' in s:
                s = s.rstrip('0').rstrip('.')
            vals.append(s)
    return vals

def resolve(sources, comp):
    for doc, loops, ext in sources:
        vals = []
        for loop in loops:
            if get_component(loop) == comp:
                vals.extend(ext(loop))
        if vals:
            uniq = set(vals)
            if len(uniq) > 1:
                return "CONFLICT"
            return [vals[0], doc]
    return "ABSENT"

def main():
    d = sys.argv[1]
    cal = parse_edi(os.path.join(d, 'calibration_log.edi'))
    lab = parse_edi(os.path.join(d, 'lab_certificates.edi'))
    tr  = parse_edi(os.path.join(d, 'test_reports.edi'))
    sp  = parse_edi(os.path.join(d, 'spec_sheets.edi'))

    comps = [f"P-402{i:02d}" for i in range(1, 17)]
    result = {}

    for c in comps:
        result[f"ea.calibration_current::{c}"] = {
            "calibration date": resolve([
                ("calibration_log", cal, lambda l: extract_date(l, '300')),
            ], c),
            "test date": resolve([
                ("test_reports", tr, lambda l: extract_date(l, '301')),
                ("lab_certificates", lab, lambda l: extract_date(l, '302')),
            ], c),
        }

    for c in comps:
        result[f"ea.load_with_margin::{c}"] = {
            "measured load": resolve([
                ("lab_certificates", lab, lambda l: extract_force(l, ['UFL'])),
                ("test_reports", tr, lambda l: extract_force(l, ['UFH'])),
            ], c),
            "specified minimum": resolve([
                ("spec_sheets", sp, lambda l: extract_force(l, ['UFM'])),
            ], c),
        }

    print(json.dumps(result, indent=2))

if __name__ == '__main__':
    main()
