import sys
import os
import json
from datetime import date, timedelta


def iso_week_to_date(s):
    """Convert ISO 8601 week date (YYYY-Www-D) to YYYY-MM-DD."""
    parts = s.split('-W')
    year = int(parts[0])
    rest = parts[1].split('-')
    week = int(rest[0])
    day = int(rest[1])
    jan4 = date(year, 1, 4)
    week1_monday = jan4 - timedelta(days=jan4.weekday())
    result = week1_monday + timedelta(weeks=week - 1, days=day - 1)
    return result.strftime('%Y-%m-%d')


def parse_tsv(filepath):
    """Parse a TSV cross-tab file.
    Returns dict: component_key -> list of record dicts (attr -> value).
    """
    with open(filepath, 'r') as f:
        content = f.read()
    lines = content.splitlines()
    data_lines = [l for l in lines if l.strip() and not l.startswith('#')]
    if not data_lines:
        return {}
    header = data_lines[0].split('\t')
    num_cols = len(header)
    records_by_key = {}
    for col_idx in range(1, num_cols):
        rec = {}
        for line in data_lines[1:]:
            fields = line.split('\t')
            attr = fields[0].strip()
            if col_idx < len(fields):
                rec[attr] = fields[col_idx].strip()
        key = rec.get('component.key', '')
        if key and key != '~':
            if key not in records_by_key:
                records_by_key[key] = []
            records_by_key[key].append(rec)
    return records_by_key


def get_values(doc_data, entity, attr):
    """Get all non-~ values for an attribute for an entity from a document."""
    if entity not in doc_data:
        return []
    values = []
    for rec in doc_data[entity]:
        val = rec.get(attr, '')
        if val and val != '~':
            values.append(val)
    return values


def resolve_fact(entity, primary_data, primary_attr, primary_doc_name,
                 fallback_data=None, fallback_attr=None, fallback_doc_name=None,
                 is_date=False):
    """Resolve a fact value from primary document, with optional fallback."""
    values = get_values(primary_data, entity, primary_attr)
    doc_name = primary_doc_name
    if not values and fallback_data is not None:
        values = get_values(fallback_data, entity, fallback_attr)
        doc_name = fallback_doc_name
    if not values:
        return "ABSENT"
    if is_date:
        converted = [iso_week_to_date(v) for v in values]
    else:
        converted = list(values)
    unique = set(converted)
    if len(unique) > 1:
        return "CONFLICT"
    return [converted[0], doc_name]


def main():
    dir_path = sys.argv[1]
    cal_log = parse_tsv(os.path.join(dir_path, 'calibration_log.tsv'))
    lab_certs = parse_tsv(os.path.join(dir_path, 'lab_certificates.tsv'))
    spec_sheets = parse_tsv(os.path.join(dir_path, 'spec_sheets.tsv'))
    test_reports = parse_tsv(os.path.join(dir_path, 'test_reports.tsv'))
    components = [f'P-403{i:02d}' for i in range(1, 17)]
    result = {}
    for comp in components:
        key1 = f'ea.calibration_current::{comp}'
        result[key1] = {
            'calibration date': resolve_fact(
                comp, cal_log, 'rig.cal.wk', 'calibration_log',
                is_date=True
            ),
            'test date': resolve_fact(
                comp, test_reports, 'inhouse.break.wk', 'test_reports',
                fallback_data=lab_certs, fallback_attr='lab.break.wk',
                fallback_doc_name='lab_certificates',
                is_date=True
            )
        }
        key2 = f'ea.load_with_margin::{comp}'
        result[key2] = {
            'measured load': resolve_fact(
                comp, lab_certs, 'lab.break.kn', 'lab_certificates',
                fallback_data=test_reports, fallback_attr='inhouse.break.kn',
                fallback_doc_name='test_reports',
                is_date=False
            ),
            'specified minimum': resolve_fact(
                comp, spec_sheets, 'floor.force.kn', 'spec_sheets',
                is_date=False
            )
        }
    print(json.dumps(result, indent=2))


if __name__ == '__main__':
    main()
