import sys
import os
import json
from decimal import Decimal

def parse_file(filepath):
    with open(filepath, 'r', encoding='utf-8-sig') as f:
        lines = f.readlines()
    header = None
    data = []
    for line in lines:
        line = line.rstrip('\r\n')
        if not line.strip():
            continue
        if line.startswith('#'):
            continue
        if header is None:
            header = line.split('|')
        else:
            data.append(line.split('|'))
    return header, data

def convert_date(s):
    if not s or not s.strip():
        return None
    s = s.strip()
    parts = s.split('/')
    if len(parts) != 3:
        return None
    m, d, y = parts
    return f"{y}-{m.zfill(2)}-{d.zfill(2)}"

def convert_force(val_str, uom_str):
    if not val_str or not val_str.strip():
        return None
    if not uom_str or not uom_str.strip():
        return None
    val_str = val_str.strip()
    uom_str = uom_str.strip().upper()
    d = Decimal(val_str)
    if uom_str == 'N':
        d = d / Decimal(1000)
    if d == int(d):
        return str(int(d))
    s = str(d)
    if 'E' in s or 'e' in s:
        s = f"{d:.10f}".rstrip('0').rstrip('.')
    elif '.' in s:
        s = s.rstrip('0').rstrip('.')
    return s

def get_values(filepath, entity, key_col, extract_fn):
    if not os.path.exists(filepath):
        return []
    header, data = parse_file(filepath)
    if header is None:
        return []
    col_map = {name: i for i, name in enumerate(header)}
    if key_col not in col_map:
        return []
    key_idx = col_map[key_col]
    results = []
    for row in data:
        if len(row) <= key_idx:
            continue
        if row[key_idx].strip() != entity:
            continue
        val = extract_fn(row, col_map)
        if val is not None:
            results.append(val)
    return results

def resolve(values, doc_name):
    if not values:
        return None
    unique = set(values)
    if len(unique) > 1:
        return "CONFLICT"
    return [values[0], doc_name]

def resolve_with_fallback(primary_values, primary_doc, fallback_values, fallback_doc):
    if primary_values:
        return resolve(primary_values, primary_doc)
    if fallback_values:
        return resolve(fallback_values, fallback_doc)
    return "ABSENT"

def extract_cal_date(row, col_map):
    idx = col_map['LOAD_FRAME_CAL_DAY']
    if idx >= len(row):
        return None
    return convert_date(row[idx])

def extract_test_date_tr(row, col_map):
    idx = col_map['INTERNAL_TRIAL_DAY']
    if idx >= len(row):
        return None
    return convert_date(row[idx])

def extract_test_date_lc(row, col_map):
    idx = col_map['ACCREDITED_TRIAL_DAY']
    if idx >= len(row):
        return None
    return convert_date(row[idx])

def extract_measured_load_lc(row, col_map):
    val_idx = col_map['ACCREDITED_ULTIMATE_FORCE']
    uom_idx = col_map['ACCREDITED_ULTIMATE_FORCE_UOM']
    if val_idx >= len(row) or uom_idx >= len(row):
        return None
    return convert_force(row[val_idx], row[uom_idx])

def extract_measured_load_tr(row, col_map):
    val_idx = col_map['INTERNAL_ULTIMATE_FORCE']
    uom_idx = col_map['INTERNAL_ULTIMATE_FORCE_UOM']
    if val_idx >= len(row) or uom_idx >= len(row):
        return None
    return convert_force(row[val_idx], row[uom_idx])

def extract_specified_min(row, col_map):
    val_idx = col_map['REQUIRED_ULTIMATE_FORCE']
    uom_idx = col_map['REQUIRED_ULTIMATE_FORCE_UOM']
    if val_idx >= len(row) or uom_idx >= len(row):
        return None
    return convert_force(row[val_idx], row[uom_idx])

def main():
    dir_path = sys.argv[1]
    entities = [f"P-404{i:02d}" for i in range(1, 17)]
    result = {}

    for entity in entities:
