import sys
import os
import json
from decimal import Decimal

def parse_file(filepath):
    records = []
    with open(filepath, 'r', encoding='utf-8') as f:
        lines = f.readlines()
    header = None
    for line in lines:
        line = line.strip()
        if not line or line.startswith('#'):
            continue
        if header is None:
            header = [h.strip() for h in line.split('|')]
            continue
        fields = [f.strip() for f in line.split('|')]
        record = {}
        for i, col in enumerate(header):
            record[col] = fields[i] if i < len(fields) else ''
        records.append(record)
    return records

def convert_date(date_str):
    if not date_str:
        return None
    parts = date_str.split('/')
    if len(parts) != 3:
        return None
    month, day, year = parts
    return f"{year}-{month.zfill(2)}-{day.zfill(2)}"

def convert_to_kn(value_str, uom):
    if not value_str:
        return None
    val = Decimal(value_str)
    if uom == 'N':
        val = val / Decimal('1000')
    return str(val)

def get_values(records, entity, field_name, uom_field=None, transform=None):
    results = []
    for rec in records:
        if rec.get('COMPONENT_CATALOG_KEY') == entity:
            val = rec.get(field_name, '')
            if val:
                if transform:
                    if uom_field:
                        uom = rec.get(uom_field, '')
                        t = transform(val, uom)
                    else:
                        t = transform(val)
                    if t is not None:
                        results.append(t)
                else:
                    results.append(val)
    return results

def resolve_fact(sources, entity):
    for doc_name, records, field_name, uom_field, transform in sources:
        values = get_values(records, entity, field_name, uom_field, transform)
        if values:
            unique = set(values)
            if len(unique) == 1:
                return [values[0], doc_name]
            else:
                return "CONFLICT"
    return "ABSENT"

def main():
    dir_path = sys.argv[1]

    docs = {}
    for name in ['calibration_log', 'lab_certificates', 'spec_sheets', 'test_reports']:
        filepath = os.path.join(dir_path, name + '.txt')
        docs[name] = parse_file(filepath)

    result = {}

    parts_list = [f'P-405{i:02d}' for i in range(1, 17)]

