import sys
import os
import re
import json
import html
from datetime import datetime

def parse_date(s):
    s = s.strip()
    # Try YYYY-MM-DD first
    try:
        datetime.strptime(s, '%Y-%m-%d')
        return s
    except ValueError:
        pass
    # Remove weekday prefix: "Wed., June 24, 2026" -> "June 24, 2026"
    m = re.match(r'\w+\.,\s*(.+)', s)
    if m:
        s = m.group(1).strip()
    # Remove period after 3-letter month abbreviation: "Feb." -> "Feb"
    s = re.sub(r'\b(\w{3})\.', r'\1', s)
    for fmt in ['%B %d, %Y', '%b %d, %Y']:
        try:
            dt = datetime.strptime(s, fmt)
            return dt.strftime('%Y-%m-%d')
        except ValueError:
            continue
    return None

def parse_amount(s):
    s = s.strip()
    m = re.search(r'([\d.]+)\s*kN', s)
    if m:
        return m.group(1)
    return None

def parse_html_file(filepath):
    with open(filepath, 'r', encoding='utf-8-sig') as f:
        content = f.read()
    sheets = re.findall(r'<article class="sheet"[^>]*>(.*?)</article>', content, re.DOTALL)
    results = {}
    for sheet in sheets:
        item_match = re.search(r'<strong[^>]*>(P-\d+)</strong>', sheet)
        if not item_match:
            continue
        item_code = item_match.group(1)
        rows = re.findall(r'<tr>\s*<th>(.*?)</th>\s*<td([^>]*)>(.*?)</td>\s*</tr>', sheet, re.DOTALL)
        for label, td_attrs, value in rows:
            label = html.unescape(label).strip()
            if 'void' in td_attrs:
                value = None
            else:
                value = re.sub(r'<[^>]+>', '', value)
                value = html.unescape(value).strip()
                if not value:
                    value = None
            if item_code not in results:
                results[item_code] = {}
            if label not in results[item_code]:
                results[item_code][label] = []
            results[item_code][label].append(value)
    return results

def get_fact_value_from_doc(data, doc_name, item_code, field_label, value_type):
    if doc_name not in data or item_code not in data[doc_name] or field_label not in data[doc_name][item_code]:
        return ('NONE', None)
    values = data[doc_name][item_code][field_label]
    non_void = [v for v in values if v is not None]
    if not non_void:
        return ('NONE', None)
    parsed = []
    for v in non_void:
        if value_type == 'date':
            p = parse_date(v)
        elif value_type == 'amount':
            p = parse_amount(v)
        else:
            p = v
        if p is not None:
            parsed.append(p)
    if not parsed:
        return ('NONE', None)
    unique = set(parsed)
    if len(unique) > 1:
        return ('CONFLICT', None)
    return ('VALUE', list(unique)[0])

def resolve_fact(data, item_code, fact_config):
    for doc_name, field_label, value_type in fact_config:
        status, value = get_fact_value_from_doc(data, doc_name, item_code, field_label, value_type)
        if status == 'CONFLICT':
            return 'CONFLICT'
        if status == 'VALUE':
            return [value, doc_name]
    return 'ABSENT'

def main():
    dir_path = sys.argv[1]
    data = {}
    files = {
        'calibration_log': 'calibration_log.html',
        'lab_certificates': 'lab_certificates.html',
        'parts': 'parts.html',
        'spec_sheets': 'spec_sheets.html',
        'test_reports': 'test_reports.html',
    }
    for doc_name, filename in files.items():
        filepath = os.path.join(dir_path, filename)
        if os.path.exists(filepath):
            data[doc_name] = parse_html_file(filepath)
        else:
            data[doc_name] = {}
    rules = {
        'ea.calibration_current': {
            'calibration date': [('calibration_log', 'Frame last calibrated', 'date')],
            'test date': [('test_reports', 'Break test performed', 'date'), ('lab_certificates', 'Laboratory test performed', 'date')],
        },
        'ea.load_with_margin': {
            'measured load': [('lab_certificates', 'Load at failure (lab certified)', 'amount'), ('test_reports', 'Load at failure (in-house)', 'amount')],
            'specified minimum': [('spec_sheets', 'Drawing minimum at failure', 'amount')],
        },
    }
    output = {}
    for rule_name in ['ea.calibration_current', 'ea.load_with_margin']:
        for i in range(1, 17):
            item_code = f'P-405{i:02d}'
            pair_id = f'{rule_name}::{item_code}'
            output[pair_id] = {}
            for fact_name, fact_config in rules[rule_name].items():
                output[pair_id][fact_name] = resolve_fact(data, item_code, fact_config)
    print(json.dumps(output, indent=2))

if __name__ == '__main__':
    main()
