import sys
import os
import re
import json

MONTH_MAP = {
    'jan': 1, 'feb': 2, 'mar': 3, 'apr': 4, 'may': 5, 'jun': 6,
    'jul': 7, 'aug': 8, 'sep': 9, 'oct': 10, 'nov': 11, 'dec': 12
}

def parse_date(text):
    text = text.strip()
    m = re.match(r'\w+\.,?\s+([A-Za-z]+)\.?\s+(\d+),?\s+(\d{4})', text)
    if m:
        month_name = m.group(1).lower()[:3]
        day = int(m.group(2))
        year = int(m.group(3))
        month = MONTH_MAP.get(month_name)
        if month:
            return f"{year:04d}-{month:02d}-{day:02d}"
    return None

def parse_amount(text):
    text = text.strip()
    m = re.search(r'(\d+(?:\.\d+)?)\s*kN', text)
    if m:
        return m.group(1)
    return None

def strip_tags(text):
    text = text.replace('&mdash;', '\u2014')
    text = text.replace('&nbsp;', ' ')
    text = text.replace('&middot;', '\u00b7')
    text = text.replace('&rsaquo;', '\u203a')
    text = text.replace('&amp;', '&')
    return re.sub(r'<[^>]+>', '', text).strip()

def parse_html_file(filepath):
    try:
        with open(filepath, 'r', encoding='utf-8') as f:
            content = f.read()
    except (FileNotFoundError, IOError):
        return {}

    sheets = re.findall(r'<article class="sheet"[^>]*>(.*?)</article>', content, re.DOTALL)

    results = {}

    for sheet in sheets:
        rows = re.findall(r'<tr><th>(.*?)</th><td([^>]*)>(.*?)</td></tr>', sheet, re.DOTALL)

        item_code = None
        fields = {}

        for th_content, td_attrs, td_content in rows:
            th_text = strip_tags(th_content)

            is_void = 'void' in td_attrs or 'left blank' in td_content

            if th_text == 'Item code':
                m = re.search(r'<strong>(.*?)</strong>', td_content)
                if m:
                    item_code = m.group(1).strip()
            else:
                if is_void:
                    fields[th_text] = None
                else:
                    fields[th_text] = strip_tags(td_content)

        if item_code:
            if item_code not in results:
                results[item_code] = {}
            for field_name, value in fields.items():
                if field_name not in results[item_code]:
                    results[item_code][field_name] = []
                results[item_code][field_name].append(value)

    return results

def get_fact_value(doc_data, item_code, field_name, value_parser=None):
    if item_code not in doc_data:
        return None, False
    if field_name not in doc_data[item_code]:
        return None, False

    raw_values = doc_data[item_code][field_name]
    non_none_values = [v for v in raw_values if v is not None]

    if not non_none_values:
        return None, False

    if value_parser:
        parsed_values = []
        for v in non_none_values:
            parsed = value_parser(v)
            if parsed is not None:
                parsed_values.append(parsed)
        if not parsed_values:
            return None, False
        unique_values = list(set(parsed_values))
    else:
        unique_values = list(set(non_none_values))

    if len(unique_values) > 1:
        return None, True

    return unique_values[0], False

def resolve_fact(primary_data, primary_name, primary_field,
                 fallback_data, fallback_name, fallback_field,
                 item_code, value_parser=None):
    value, is_conflict = get_fact_value(primary_data, item_code, primary_field, value_parser)

    if is_conflict:
        return "CONFLICT"

    if value is not None:
        return [value, primary_name]

    if fallback_data is not None and fallback_name is not None:
        value, is_conflict = get_fact_value(fallback_data, item_code, fallback_field, value_parser)
        if is_conflict:
            return "CONFLICT"
        if value is not None:
            return [value, fallback_name]

    return "ABSENT"

def main():
    directory = sys.argv[1]

    calib_data = parse_html_file(os.path.join(directory, 'calibration_log.html'))
    lab_data = parse_html_file(os.path.join(directory, 'lab_certificates.html'))
    test_data = parse_html_file(os.path.join(directory, 'test_reports.html'))
    spec_data = parse_html_file(os.path.join(directory, 'spec_sheets.html'))

    item_codes = [f"P-406{i:02d}" for i in range(1, 17)]

    output = {}

    for item_code in item_codes:
        pair_id = f"ea.calibration_current::{item_code}"
        output[pair_id] = {
            "calibration date": resolve_fact(
                calib_data, "calibration_log", "Frame last calibrated",
                None, None, None,
                item_code, parse_date
            ),
            "test date": resolve_fact(
                test_data, "test_reports", "Break test performed",
                lab_data, "lab_certificates", "Laboratory test performed",
                item_code, parse_date
            )
        }

    for item_code in item_codes:
        pair_id = f"ea.load_with_margin::{item_code}"
        output[pair_id] = {
            "measured load": resolve_fact(
                lab_data, "lab_certificates", "Load at failure (lab certified)",
                test_data, "test_reports", "Load at failure (in-house)",
                item_code, parse_amount
            ),
            "specified minimum": resolve_fact(
                spec_data, "spec_sheets", "Drawing minimum at failure",
                None, None, None,
                item_code, parse_amount
            )
        }

    print(json.dumps(output, indent=2))

if __name__ == '__main__':
    main()
