    for table, cols, vals in matches:
        col_names = [c.strip() for c in cols.split(',')]
        tuples = re.findall(r'\(([^)]*)\)', vals)
        for tup in tuples:
            values = parse_values(tup)
            row = dict(zip(col_names, values))
            results.append(row)
    return results

def parse_values(s):
    values = []
    current = ''
    in_string = False
    for c in s:
        if c == "'":
            in_string = not in_string
            current += c
        elif c == ',' and not in_string:
            values.append(current.strip())
            current = ''
        else:
            current += c
    values.append(current.strip())
    parsed = []
    for v in values:
        v = v.strip()
        if v.upper() == 'NULL':
            parsed.append(None)
        elif v.startswith("'") and v.endswith("'"):
            parsed.append(v[1:-1])
        else:
            parsed.append(v)
    return parsed

