        values = get_values_for_entity(records, entity, field_name)
        if not values:
            continue
        converted = set()
        for v in values:
            converted.add(convert_func(v))
        if len(converted) == 1:
            return [list(converted)[0], doc_name]
        else:
            return "CONFLICT"
    return "ABSENT"

def main():
