from decimal import Decimal

def parse_edi(filepath):
    if not os.path.exists(filepath):
        return []
    with open(filepath, 'r') as f:
        content = f.read()
    content = content.replace('\n', '').replace('\r', '')
    segments = content.split('~')
    segments = [s.strip() for s in segments if s.strip()]
    loops = []
    current_loop = None
    for seg in segments:
        parts = seg.split('*')
        tag = parts[0]
        if tag == 'LX':
            if current_loop is not None:
                loops.append(current_loop)
            current_loop = []
            current_loop.append(parts)
        elif current_loop is not None:
            current_loop.append(parts)
    if current_loop is not None:
        loops.append(current_loop)
    return loops

def extract_loop_data(loop_segments):
    data = {'part': None, 'dtp': {}, 'mea': {}}
    for seg in loop_segments:
        tag = seg[0]
        if tag == 'LIN':
            if len(seg) >= 4 and seg[2] == 'BP':
                data['part'] = seg[3]
        elif tag == 'DTP':
            if len(seg) >= 4:
                data['dtp'].setdefault(seg[1], []).append(seg[3])
        elif tag == 'MEA':
            if len(seg) >= 5 and seg[1] == 'TE':
                data['mea'].setdefault(seg[2], []).append((seg[3], seg[4]))
    return data

def convert_to_kn(value_str, unit):
    v = Decimal(value_str)
    if unit == 'KN':
        return v
    elif unit == 'NT':
        return v / Decimal(1000)
    return v

def format_date(d):
    return f"{d[0:4]}-{d[4:6]}-{d[6:8]}"

def format_decimal(d):
    s = f"{d:f}"
    if '.' in s:
        s = s.rstrip('0').rstrip('.')
    return s

def build_doc_index(loops):
    index = {}
    for loop_segments in loops:
        data = extract_loop_data(loop_segments)
        if data['part']:
            index.setdefault(data['part'], []).append(data)
    return index

def get_fact_values(doc_index, part, fact_type, fact_code):
    if part not in doc_index:
        return []
    values = []
    for loop_data in doc_index[part]:
        if fact_type in loop_data and fact_code in loop_data[fact_type]:
            values.extend(loop_data[fact_type][fact_code])
    return values

def resolve_date(doc_indices, part, doc_specs):
    for doc_name, dtp_code in doc_specs:
        values = get_fact_values(doc_indices[doc_name], part, 'dtp', dtp_code)
        if values:
            if len(set(values)) > 1:
                return "CONFLICT"
            return [format_date(values[0]), doc_name]
    return "ABSENT"

def resolve_kn(doc_indices, part, doc_specs):
    for doc_name, mea_code in doc_specs:
        values = get_fact_values(doc_indices[doc_name], part, 'mea', mea_code)
        if values:
            kn_values = [convert_to_kn(v, u) for v, u in values]
            if len(set(kn_values)) > 1:
                return "CONFLICT"
            return [format_decimal(kn_values[0]), doc_name]
    return "ABSENT"

def main():
    dir_path = sys.argv[1]
    doc_names = ['calibration_log', 'lab_certificates', 'parts', 'test_reports', 'spec_sheets']
    doc_indices = {}
    for name in doc_names:
        filepath = os.path.join(dir_path, f'{name}.edi')
        doc_indices[name] = build_doc_index(parse_edi(filepath))
    all_parts = set()
    for idx in doc_indices.values():
