    with open(filepath, 'r') as f:
        content = f.read()
    segments = content.split('~')
    records = []
    current_record = None
    for seg in segments:
        seg = seg.strip()
        if not seg:
            continue
        parts = seg.split('*')
        tag = parts[0]
        if tag == 'LX':
            if current_record is not None:
                records.append(current_record)
            current_record = {'segments': []}
        elif current_record is not None:
            current_record['segments'].append(parts)
    if current_record is not None:
        records.append(current_record)
    return records

def get_part_key(record):
    for seg in record['segments']:
        if seg[0] == 'LIN':
            for i, val in enumerate(seg):
                if val == 'BP' and i + 1 < len(seg):
                    return seg[i + 1]
    return None

def get_dtp_date(record, qualifier):
    for seg in record['segments']:
        if seg[0] == 'DTP' and len(seg) >= 4 and seg[1] == qualifier and seg[2] == 'D8':
            return format_date(seg[3])
    return None

def get_mea_value(record, ref_id):
    for seg in record['segments']:
        if seg[0] == 'MEA' and len(seg) >= 5 and seg[1] == 'TE' and seg[2] == ref_id:
            value = seg[3]
            unit = seg[4]
            return convert_to_kn(value, unit)
    return None

def format_date(date_str):
    if len(date_str) == 8:
        return f"{date_str[:4]}-{date_str[4:6]}-{date_str[6:8]}"
    return date_str

def convert_to_kn(value, unit):
    d = Decimal(value)
    if unit == 'KN':
        return d
    elif unit == 'NT':
        return d / Decimal(1000)
    return d

def format_decimal(d):
    normalized = d.normalize()
    s = str(normalized)
    if 'E' in s or 'e' in s:
        s = format(normalized, 'f')
    return s

def collect_field_values(records, part_key, extractor):
    values = []
    for record in records:
        key = get_part_key(record)
        if key == part_key:
            val = extractor(record)
            if val is not None:
                values.append(val)
    return values

def resolve_fact(values, doc_name):
    if len(values) == 0:
        return "ABSENT"
    first = values[0]
    all_same = all(v == first for v in values)
    if all_same:
        if isinstance(first, Decimal):
            return [format_decimal(first), doc_name]
        else:
            return [str(first), doc_name]
    else:
        return "CONFLICT"

def main():
    dir_path = sys.argv[1]

    calibration_log = parse_edi(os.path.join(dir_path, 'calibration_log.edi'))
    lab_certificates = parse_edi(os.path.join(dir_path, 'lab_certificates.edi'))
    spec_sheets = parse_edi(os.path.join(dir_path, 'spec_sheets.edi'))
    test_reports = parse_edi(os.path.join(dir_path, 'test_reports.edi'))

    def cal_date_extractor(record):
        return get_dtp_date(record, '300')

    def test_date_tr_extractor(record):
        return get_dtp_date(record, '301')

    def test_date_lc_extractor(record):
        return get_dtp_date(record, '302')

    def ufl_extractor(record):
        return get_mea_value(record, 'UFL')

    def ufh_extractor(record):
        return get_mea_value(record, 'UFH')

    def ufm_extractor(record):
        return get_mea_value(record, 'UFM')

    part_keys = [f'P-408{i:02d}' for i in range(1, 17)]

    result = {}

    for part in part_keys:
        pair_id = f'ea.calibration_current::{part}'

        cal_values = collect_field_values(calibration_log, part, cal_date_extractor)
        cal_result = resolve_fact(cal_values, 'calibration_log')

        tr_test_values = collect_field_values(test_reports, part, test_date_tr_extractor)
        if len(tr_test_values) > 0:
            test_result = resolve_fact(tr_test_values, 'test_reports')
        else:
            lc_test_values = collect_field_values(lab_certificates, part, test_date_lc_extractor)
            test_result = resolve_fact(lc_test_values, 'lab_certificates')

        result[pair_id] = {
            'calibration date': cal_result,
            'test date': test_result
        }

    for part in part_keys:
        pair_id = f'ea.load_with_margin::{part}'

        lc_ufl_values = collect_field_values(lab_certificates, part, ufl_extractor)
        if len(lc_ufl_values) > 0:
            measured_result = resolve_fact(lc_ufl_values, 'lab_certificates')
        else:
            tr_ufh_values = collect_field_values(test_reports, part, ufh_extractor)
            measured_result = resolve_fact(tr_ufh_values, 'test_reports')

        ufm_values = collect_field_values(spec_sheets, part, ufm_extractor)
        spec_result = resolve_fact(ufm_values, 'spec_sheets')

        result[pair_id] = {
            'measured load': measured_result,
            'specified minimum': spec_result
        }

    print(json.dumps(result, indent=2))

if __name__ == '__main__':
