import sys
import os
import json
import re
from datetime import date

def parse_iso_week(week_str):
    m = re.match(r'(\d{4})-W(\d{2})-(\d)', week_str)
    if not m:
        return week_str
    year = int(m.group(1))
    week = int(m.group(2))
    day = int(m.group(3))
    d = date.fromisocalendar(year, week, day)
    return d.isoformat()

def read_tsv(path):
    with open(path, 'r') as f:
        lines = f.read().splitlines()
    data_lines = [l for l in lines if not l.startswith('#') and l.strip()]
    if not data_lines:
        return {}, []
    header = data_lines[0].split('\t')
    n_records = len(header) - 1
    attr_values = {}
    for line in data_lines[1:]:
        parts = line.split('\t')
        attr = parts[0]
        values = parts[1:]
        while len(values) < n_records:
            values.append('')
        attr_values[attr] = values
    keys = attr_values.get('component.key', [])
    return attr_values, keys

def get_values_for_entity(attr_values, keys, entity, attr_name):
    values = []
    if attr_name not in attr_values:
        return values
    attr_row = attr_values[attr_name]
    for i, k in enumerate(keys):
        if k == entity:
            v = attr_row[i] if i < len(attr_row) else ''
            if v and v != '~':
                values.append(v)
    return values

def resolve_fact(primary_doc, primary_name, primary_attr, fallback_doc, fallback_name, fallback_attr, entity, transform=None):
    def get_from(doc, attr_name):
        if doc is None:
            return (None, None)
        attr_values, keys = doc
        vals = get_values_for_entity(attr_values, keys, entity, attr_name)
        if not vals:
            return (None, None)
        distinct = set(vals)
        if len(distinct) > 1:
            return ("CONFLICT", None)
        v = vals[0]
        if transform:
            v = transform(v)
        return (v, "present")

    val, status = get_from(primary_doc, primary_attr)
    if status == "CONFLICT":
        return "CONFLICT"
    if status == "present":
        return [val, primary_name]
    val, status = get_from(fallback_doc, fallback_attr)
    if status == "CONFLICT":
        return "CONFLICT"
    if status == "present":
        return [val, fallback_name]
    return "ABSENT"

def main():
    dir_path = sys.argv[1]

    def load_doc(filename):
        path = os.path.join(dir_path, filename)
        if os.path.exists(path):
            return read_tsv(path)
        return None

    cal_log = load_doc('calibration_log.tsv')
    lab_certs = load_doc('lab_certificates.tsv')
    spec_sheets = load_doc('spec_sheets.tsv')
    test_reports = load_doc('test_reports.tsv')

    entities = [f'P-409{i:02d}' for i in range(1, 17)]

    result = {}

    for entity in entities:
        pair_id = f'ea.calibration_current::{entity}'
        cal_date = resolve_fact(cal_log, 'calibration_log', 'rig.cal.wk',
                                None, None, None, entity, parse_iso_week)
        test_date = resolve_fact(test_reports, 'test_reports', 'inhouse.break.wk',
                                 lab_certs, 'lab_certificates', 'lab.break.wk',
                                 entity, parse_iso_week)
        result[pair_id] = {
            'calibration date': cal_date,
            'test date': test_date
        }

        pair_id = f'ea.load_with_margin::{entity}'
        measured_load = resolve_fact(lab_certs, 'lab_certificates', 'lab.break.kn',
                                     test_reports, 'test_reports', 'inhouse.break.kn',
                                     entity)
        specified_min = resolve_fact(spec_sheets, 'spec_sheets', 'floor.force.kn',
                                      None, None, None, entity)
        result[pair_id] = {
            'measured load': measured_load,
            'specified minimum': specified_min
        }

    print(json.dumps(result, indent=2))

if __name__ == '__main__':
