def parse_tsv(filepath):
    with open(filepath, 'r') as f:
        lines = f.readlines()

    data_lines = [l.rstrip('\r\n') for l in lines if not l.startswith('#') and l.strip()]

    if not data_lines:
        return []

    header = data_lines[0].split('\t')

    records = []
    for col_idx in range(1, len(header)):
        record = {}
        for line in data_lines[1:]:
            fields = line.split('\t')
            if len(fields) > 0:
                attr = fields[0]
                if col_idx < len(fields):
                    record[attr] = fields[col_idx].strip()
                else:
                    record[attr] = '~'
        records.append(record)

    return records

def get_values_for_component(records, component_key, attribute):
    values = []
    for record in records:
        ck = record.get('component.key', '')
        if ck is not None:
            ck = ck.strip()
        if ck == component_key:
            val = record.get(attribute, '~')
            if val is not None:
                val = val.strip()
            if val and val != '~':
                values.append(val)
    return values

def week_to_date(week_str):
    parts = week_str.split('-')
    year = int(parts[0])
    week = int(parts[1].replace('W', ''))
    day = int(parts[2])
    d = datetime.date.fromisocalendar(year, week, day)
    return d.strftime('%Y-%m-%d')

def resolve_with_fallback(primary_records, primary_attr, primary_doc,
                            fallback_records, fallback_attr, fallback_doc,
                            component_key, is_date=False):
    values = get_values_for_component(primary_records, component_key, primary_attr)
    if values:
        if len(set(values)) == 1:
            if is_date:
                return [week_to_date(values[0]), primary_doc]
            else:
                return [values[0], primary_doc]
        else:
            return 'CONFLICT'

    if fallback_records is not None:
        values = get_values_for_component(fallback_records, component_key, fallback_attr)
        if values:
            if len(set(values)) == 1:
                if is_date:
                    return [week_to_date(values[0]), fallback_doc]
                else:
                    return [values[0], fallback_doc]
            else:
                return 'CONFLICT'

    return 'ABSENT'

def resolve_single_doc(records, attr, doc_name, component_key, is_date=False):
    values = get_values_for_component(records, component_key, attr)
    if not values:
        return 'ABSENT'
    if len(set(values)) == 1:
        if is_date:
            return [week_to_date(values[0]), doc_name]
        else:
            return [values[0], doc_name]
    else:
        return 'CONFLICT'

def main():
    dir_path = sys.argv[1]

    calibration_log = parse_tsv(os.path.join(dir_path, 'calibration_log.tsv'))
    lab_certificates = parse_tsv(os.path.join(dir_path, 'lab_certificates.tsv'))
    spec_sheets = parse_tsv(os.path.join(dir_path, 'spec_sheets.tsv'))
