            comp, is_date=True)

        result[pair_id] = {
            'calibration date': cal_date,
            'test date': test_date
        }

        # ea.load_with_margin
        pair_id2 = f'ea.load_with_margin::{comp}'

        measured_load = resolve_with_fallback(
            lab_certificates, 'lab.break.kn', 'lab_certificates',
            test_reports, 'inhouse.break.kn', 'test_reports',
            comp, is_date=False)

        spec_min = resolve_single_doc(spec_sheets, 'floor.force.kn', 'spec_sheets', comp, is_date=False)

        result[pair_id2] = {
            'measured load': measured_load,
            'specified minimum': spec_min
        }

    print(json.dumps(result, indent=2))

if __name__ == '__main__':
