import sys
import os
import json
from decimal import Decimal

def parse_file(filepath):
    with open(filepath, 'r', encoding='utf-8-sig') as f:
        lines = f.readlines()
    header = None
    data_lines = []
    for line in lines:
        line = line.rstrip('\n').rstrip('\r')
        if not line.strip():
            continue
        if line.startswith('#'):
            continue
        if header is None:
            header = line.split('|')
        else:
            data_lines.append(line.split('|'))
    return header, data_lines

def get_rows_for_entity(filepath, entity):
    if not os.path.exists(filepath):
        return []
    header, data_lines = parse_file(filepath)
    if header is None:
        return []
    try:
        key_idx = header.index('COMPONENT_CATALOG_KEY')
    except ValueError:
        return []
    rows = []
    for parts in data_lines:
        while len(parts) < len(header):
            parts.append('')
        if len(parts) > key_idx and parts[key_idx] == entity:
            rows.append(dict(zip(header, parts)))
    return rows

def convert_date(val):
    m, d, y = val.split('/')
    return f"{y}-{m.zfill(2)}-{d.zfill(2)}"

def convert_force_to_kn(val, uom):
    v = Decimal(val)
    if uom == 'N':
        v = v / Decimal(1000)
    s = str(v)
    if '.' in s:
        s = s.rstrip('0').rstrip('.')
    return s

def extract_fact(directory, entity, doc_configs):
    for doc_config in doc_configs:
        doc_name = doc_config['doc']
        col = doc_config['col']
        uom_col = doc_config.get('uom_col')
        value_type = doc_config.get('type')
        filepath = os.path.join(directory, doc_name + '.txt')
        rows = get_rows_for_entity(filepath, entity)
        values = []
        for row in rows:
            val = row.get(col, '').strip()
            if val:
                if uom_col:
                    uom = row.get(uom_col, '').strip()
                    values.append(convert_force_to_kn(val, uom))
                elif value_type == 'date':
                    values.append(convert_date(val))
                else:
                    values.append(val)
        if values:
            if len(set(values)) > 1:
                return "CONFLICT"
            return [values[0], doc_name]
    return "ABSENT"

def main():
    directory = sys.argv[1]
    rules = {
        'ea.calibration_current': {
            'calibration date': [
                {'doc': 'calibration_log', 'col': 'LOAD_FRAME_CAL_DAY', 'type': 'date'}
            ],
            'test date': [
                {'doc': 'test_reports', 'col': 'INTERNAL_TRIAL_DAY', 'type': 'date'},
                {'doc': 'lab_certificates', 'col': 'ACCREDITED_TRIAL_DAY', 'type': 'date'}
            ]
        },
        'ea.load_with_margin': {
            'measured load': [
                {'doc': 'lab_certificates', 'col': 'ACCREDITED_ULTIMATE_FORCE', 'uom_col': 'ACCREDITED_ULTIMATE_FORCE_UOM'},
                {'doc': 'test_reports', 'col': 'INTERNAL_ULTIMATE_FORCE', 'uom_col': 'INTERNAL_ULTIMATE_FORCE_UOM'}
            ],
            'specified minimum': [
                {'doc': 'spec_sheets', 'col': 'REQUIRED_ULTIMATE_FORCE', 'uom_col': 'REQUIRED_ULTIMATE_FORCE_UOM'}
            ]
        }
    }
    entities = [f'P-41{i:03d}' for i in range(1, 17)]
    result = {}
    for rule_name in rules:
        for entity in entities:
            pair_id = f'{rule_name}::{entity}'
            fact_result = {}
            for fact_name, doc_configs in rules[rule_name].items():
                fact_result[fact_name] = extract_fact(directory, entity, doc_configs)
            result[pair_id] = fact_result
    print(json.dumps(result, indent=2))

if __name__ == '__main__':
    main()
